-- Native dependency change clock. Global invalidation is conservative; never source scope proof.
CREATE TABLE compose_context_clock(singleton INTEGER PRIMARY KEY CHECK(singleton=1),revision INTEGER NOT NULL CHECK(revision>=0));
INSERT INTO compose_context_clock VALUES(1,0);
CREATE TABLE compose_context_memberships(conversation_id TEXT NOT NULL,business_id TEXT NOT NULL,PRIMARY KEY(conversation_id,business_id));
INSERT INTO compose_context_memberships SELECT id,business_team_id FROM conversations WHERE business_team_id IS NOT NULL;
CREATE TRIGGER compose_member_insert AFTER INSERT ON conversations WHEN NEW.business_team_id IS NOT NULL BEGIN INSERT OR IGNORE INTO compose_context_memberships VALUES(NEW.id,NEW.business_team_id); END;
CREATE TRIGGER compose_member_update AFTER UPDATE OF business_team_id ON conversations WHEN NEW.business_team_id IS NOT NULL BEGIN INSERT OR IGNORE INTO compose_context_memberships VALUES(NEW.id,NEW.business_team_id); END;
CREATE TRIGGER compose_member_immutable_update BEFORE UPDATE ON compose_context_memberships BEGIN SELECT RAISE(ABORT,'Compose membership audit immutable'); END;
CREATE TRIGGER compose_member_immutable_delete BEFORE DELETE ON compose_context_memberships BEGIN SELECT RAISE(ABORT,'Compose membership audit immutable'); END;
CREATE TRIGGER compose_clock_users_insert AFTER INSERT ON users BEGIN UPDATE compose_context_clock SET revision=revision+1 WHERE singleton=1; END;
CREATE TRIGGER compose_clock_users_update AFTER UPDATE ON users BEGIN UPDATE compose_context_clock SET revision=revision+1 WHERE singleton=1; END;
CREATE TRIGGER compose_clock_users_delete AFTER DELETE ON users BEGIN UPDATE compose_context_clock SET revision=revision+1 WHERE singleton=1; END;
