-- Mutable ordinary drafts can be deleted by cascading conversation removal. Preserve
-- unresolved coverage instead of allowing fresh inventory to interpret deletion as clearance.
CREATE TABLE compose_context_deleted_drafts(id INTEGER PRIMARY KEY,draft_id TEXT NOT NULL,business_id TEXT NOT NULL,prior_json TEXT NOT NULL);
CREATE TRIGGER compose_deleted_draft BEFORE DELETE ON bot_message_drafts BEGIN
 INSERT INTO compose_context_deleted_drafts(draft_id,business_id,prior_json)
 SELECT OLD.id,business_id,json_object('id',OLD.id,'conversation_id',OLD.conversation_id,'version',OLD.version,'state',OLD.state,'payload_json',OLD.payload_json,'receipt',OLD.receipt,'claim_key',OLD.claim_key)
 FROM compose_context_memberships WHERE conversation_id=OLD.conversation_id;
END;
CREATE TRIGGER compose_deleted_draft_no_update BEFORE UPDATE ON compose_context_deleted_drafts BEGIN SELECT RAISE(ABORT,'Deleted draft coverage immutable'); END;
CREATE TRIGGER compose_deleted_draft_no_delete BEFORE DELETE ON compose_context_deleted_drafts BEGIN SELECT RAISE(ABORT,'Deleted draft coverage immutable'); END;
